<script lang="ts">
	import{onMount}from'svelte';import Money from'$lib/components/Money.svelte';let items=$state<any[]>([]),stateFilter=$state(''),loading=$state(true),error=$state('');async function load(){loading=true;error='';const r=await fetch(`/api/v1/ops/disputes?state=${stateFilter}`,{credentials:'include'});const d=await r.json().catch(()=>({}));loading=false;if(!r.ok){error=d.detail??'Disputes could not be loaded.';return}items=d.disputes??[]};onMount(load);
</script>
<svelte:head><title>Disputes — Kredit admin</title></svelte:head>
